class Mobile {

    String brand;
    String model;
    double price;

    Mobile() {
        this("Unknown");
    }

    Mobile(String brand) {
        this(brand, "Unknown", 0.0);
    }

    Mobile(String brand, String model, double price) {
        this.brand = brand;
        this.model = model;
        this.price = price;
    }

    void displayDetails() {
        System.out.println("Brand : " + brand);
        System.out.println("Model : " + model);
        System.out.println("Price : " + price);
    }
}

public class App {

    public static void main(String[] args) {

        Mobile m1 = new Mobile();
        Mobile m2 = new Mobile("Samsung");
        Mobile m3 = new Mobile("Samsung", "Galaxy", 50000);

        m1.displayDetails();
        m2.displayDetails();
        m3.displayDetails();
    }
}

void displayDetails() {
    System.out.println("Brand : " + brand);
    System.out.println("Model : " + model);
    System.out.println("Price : " + price);
}

